function numIslands(grid) {
  // Union-find over land cells: every merge of two islands lowers the count.
  const R = grid.length, C = grid[0].length;
  const parent = new Array(R * C).fill(-1);
  const find = (x) => {
    while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
    return x;
  };
  let count = 0;
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (grid[r][c] === 1) { parent[r * C + c] = r * C + c; count++; }
  const union = (a, b) => {
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; count--; }
  };
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] !== 1) continue;
      if (r + 1 < R && grid[r + 1][c] === 1) union(r * C + c, (r + 1) * C + c);
      if (c + 1 < C && grid[r][c + 1] === 1) union(r * C + c, r * C + c + 1);
    }
  }
  return count;
}

